class Solution {
public:
    int maxDistinctElements(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        long long next = LLONG_MIN / 2;
        int count = 0;
        for (int x : nums) {
            long long lo = (long long)x - k;
            long long hi = (long long)x + k;
            long long pick = max(lo, next);
            if (pick <= hi) {
                count++;
                next = pick + 1;
            }
        }
        return count;
    }
};
